        typeof event.id !== "string" ||
        event.id.length === 0 ||
        orders[event.id] !== undefined ||
        typeof event.item !== "string" ||
        event.item.length === 0 ||
        !Number.isInteger(event.qty) ||
        (event.qty as number) < 1
      ) {
        const why =
          orders[event.id] !== undefined
            ? "duplicate order"
            : typeof event.item !== "string" || event.item.length === 0
              ? "bad item"
              : !Number.isInteger(event.qty) || (event.qty as number) < 1
                ? "bad qty"
                : "bad id";
        return { ok: false, error: "event " + index + ": " + why };
      }
      if ((stock[event.item] ?? 0) >= (event.qty as number)) {
        stock[event.item] = (stock[event.item] ?? 0) - (event.qty as number);
        reserved[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "reserved";
      } else {
