        typeof event.id !== "string" ||
        event.id.length === 0 ||
        (event.qty !== undefined &&
          (!Number.isInteger(event.qty) || (event.qty as number) < 1))
      ) {
        const why =
          event.qty !== undefined &&
          (!Number.isInteger(event.qty) || (event.qty as number) < 1)
            ? "bad qty"
            : "bad id";
